function deepCopy(entry) {
  let theCopy = (entry.constructor === Array) ? [] : {};

  for (let key in entry) {
    if (entry.constructor === Object) {
      if (entry[key].constructor === Array) {
        theCopy = {
          ...theCopy,
          [key]: deepCopy([...entry[key]])};
      } else if (entry[key].constructor === Object) {
        theCopy = {
          ...theCopy,
          [key]: deepCopy({...entry[key]}) };
      } else {
        theCopy = {...theCopy, [key]: entry[key]};
      }
    } else {
      if (entry[key].constructor === Array) {
        theCopy = [
          ...theCopy,
          deepCopy([...entry[key]])];
      } else if (entry[key].constructor === Object) {
        theCopy = [
          ...theCopy,
          deepCopy({...entry[key]})];
      } else {
        theCopy = [...theCopy, entry[key]];
      }
    }
  }
  return theCopy;
}

